  color: var(--red);
  background: rgba(255, 51, 85, 0.15);
  text-decoration: underline;
}
.transmission-pane .char-current {
  background: rgba(0, 255, 136, 0.15);
  border-bottom: 2px solid var(--green);
}
.transmission-pane .char-pending {
  color: var(--gray);
}

.lanes {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.lane {
  display: flex;
  align-items: center;
  gap: 8px;
}

.lane-label {
  width: 60px;
  font-size: 11px;
  flex-shrink: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lane-bar-wrap {
  flex: 1;
  height: 18px;
  background: var(--bg);
  border: 1px solid var(--border);
  position: relative;
  overflow: hidden;
}

.lane-bar-fill {
  height: 100%;
  transition: width 0.15s;
}

.lane-bar-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  padding: 0 6px;
  font-size: 10px;
  color: var(--white);
  letter-spacing: 1px;
}

.lane-stats {
  width: 100px;
  font-size: 10px;
  color: var(--gray);
  text-align: right;
  flex-shrink: 0;
}

.lane.active .lane-bar-wrap {
  border-color: var(--green-dim);
}

.race-type-area {
  margin-top: auto;
  display: flex;
  gap: 8px;
  align-items: center;
}

.race-type-area .input {
  flex: 1;
  font-size: 16px;
  letter-spacing: 1px;
}

.race-controls {
  display: flex;
  gap: 8px;
}

/* ─── Results ─── */

.results {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  justify-content: center;
}

.winner-callsign {
  font-size: 24px;
  color: var(--amber);
  letter-spacing: 3px;
  text-transform: uppercase;
  text-shadow: 0 0 10px rgba(255, 176, 0, 0.3);
}

.rank-table {
  width: 100%;
  border-collapse: collapse;
}

.rank-table th {
  font-size: 10px;
  color: var(--gray);
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  text-align: left;
}

.rank-table td {
  padding: 6px 8px;
  font-size: 12px;
  border-bottom: 1px solid var(--border);
}

.rank-table tr:last-child td {
  border-bottom: none;
}

.rank-1 td {
  color: var(--amber);
}
.rank-1 td:first-child::after {
  content: ' ★';
}

.results-actions {
  display: flex;
  gap: 8px;
  margin-top: 8px;
}

/* ─── History ─── */

.history {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.history-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  font-size: 12px;
}

.history-item .winner {
  color: var(--amber);
}

.history-empty {
  color: var(--gray);
  text-align: center;
  padding: 24px;
}

/* ─── Settings ─── */

.settings {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--border);
}

.setting-row label {
  font-size: 12px;
  color: var(--white);
}

.setting-row select,
.setting-row input[type="checkbox"] {
  font-family: var(--font);
  font-size: 12px;
  padding: 4px 8px;
  background: var(--bg);
  border: 1px solid var(--border);
  color: var(--white);
}

/* ─── Demo Desk ─── */

.demo-desk {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-items: center;
  justify-content: center;
}

.demo-info {
  color: var(--gray);
  font-size: 12px;
  text-align: center;
}

/* ─── Countdown ─── */

.countdown {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  color: var(--green);
  text-shadow: 0 0 20px rgba(0, 255, 136, 0.5);
}

/* ─── Transitions / Animate ─── */

.fade-in {
  animation: fadeIn 0.2s ease-in;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* ─── Scrollbar for view ─── */

.view {
  scrollbar-width: thin;
  scrollbar-color: var(--border) var(--surface);
}

